jobs := make(chan string, 8)
results := make(chan int, 8)

go func() {
    for job := range jobs {
        results <- len(job)
    }
}()

select {
case value := <-results:
    println(value)
case <-ctx.Done():
    return ctx.Err()
}

generation := beginRequest()
go func() {
    result, err := load(ctx)
    if currentGeneration() != generation {
        return
    }
    publish(result, err)
}()
